        { "id": "l2q12", "question_text": "What does the natural history wing contain, besides dinosaur skeletons?", "type": "fill_blank", "correct_answer": "mineral collection", "explanation": "The guide mentions the mineral collection alongside the dinosaur skeletons." },
        { "id": "l2q13", "question_text": "How long after the museum closes does the cafe stay open?", "type": "fill_blank", "correct_answer": "half an hour", "explanation": "The guide states the cafe stays open until half an hour after closing." },
        { "id": "l2q14", "question_text": "What can visitors sit in on the first floor?", "type": "multiple_choice", "options": ["A cinema seat", "A reconstructed schoolroom", "A museum cafe booth"], "correct_answer": "A reconstructed schoolroom", "explanation": "The guide describes a reconstructed nineteenth-century schoolroom visitors can sit in." },
