        { "id": "l4q32", "question_text": "Roughly what proportion of marine species do reefs support?", "type": "fill_blank", "correct_answer": "a quarter", "explanation": "The lecturer says reefs support around a quarter of all known marine species." },
        { "id": "l4q33", "question_text": "What are corals actually made up of?", "type": "multiple_choice", "options": ["Plants", "Colonies of tiny animals called polyps", "Mineral deposits only"], "correct_answer": "Colonies of tiny animals called polyps", "explanation": "The lecturer explains corals are colonies of polyps, not plants." },
        { "id": "l4q34", "question_text": "What do polyps secrete to build the reef structure?", "type": "fill_blank", "correct_answer": "calcium carbonate skeleton", "explanation": "The lecturer states polyps secrete a hard calcium carbonate skeleton." },
        { "id": "l4q35", "question_text": "What is the name of the algae that live inside coral tissue?", "type": "fill_blank", "correct_answer": "zooxanthellae", "explanation": "The lecturer names this algae directly." },
        { "id": "l4q36", "question_text": "What does the coral provide to the algae in return for nutrients?", "type": "multiple_choice", "options": ["Shelter and compounds for photosynthesis", "Extra sunlight", "Transportation to new reefs"], "correct_answer": "Shelter and compounds for photosynthesis", "explanation": "The lecturer says the coral provides shelter and compounds the algae need." },
