        { "id": "l4q40", "question_text": "Name one conservation approach mentioned besides marine protected areas.", "type": "multiple_choice", "options": ["Breeding heat-resistant coral strains", "Banning all ocean tourism", "Removing all algae from reefs"], "correct_answer": "Breeding heat-resistant coral strains", "explanation": "The lecturer mentions breeding heat-resistant coral strains in laboratories as one approach." }
